@startuml

class Center {
  + name : string
  + address : string
}

class Room {
  + number : int
  + capacity : int
}

class Person {
  + firstName : string
  + lastName : string
  + birthDate : date
}

class Trainer {
  + diploma : string
}

class Prospect {}
class Intern {}

class Session {
  + startDate : date
  + startHour : time
}

class GroupSession {
  + type : string
}

class IndividualSession {}

Person "1" -- "*" Session
Trainer "0..1" -- "*" GroupSession
GroupSession "*" -- "1" Room
IndividualSession "*" -- "1" Room
Center "1" *-- "*" Room

@enduml

